"""
System-level utilities and helper functions.
"""

import errno

try:
    from eventlet import sleep
except ImportError:
    from time import sleep

import functools
import os
import platform
import subprocess
import sys
import uuid

import iso8601
from webob import exc

from glance.common import exception
